from author import *
begin("email-accounts")
fixed("A staff handle is @ followed by exactly six lowercase ASCII letters; no digits or punctuation.","@","abcdefghijklmnopqrstuvwxyz",6)
fixed("A service mailbox has exactly four lowercase ASCII letters before the literal suffix +bot@ops.test. Nothing else.","","abcdefghijklmnopqrstuvwxyz",4,"+bot@ops.test")
fixed("An account number is acct_ followed by exactly eight ASCII digits. Leading zeros are accepted.","acct_","0123456789",8)
fixed("A recovery alias is r- followed by exactly eight lowercase hexadecimal characters.","r-","0123456789abcdef",8)
fixed("The directory login is exactly five uppercase ASCII letters followed by literal @STAFF. No domain parsing is involved.","","ABCDEFGHIJKLMNOPQRSTUVWXYZ",5,"@STAFF")
bounded("A bot username is bot followed by a canonical integer 1 through 40, no padding, spaces or separators.","bot",1,40,r"(?:[1-9]|[1-3][0-9]|40)")
C("A project mailbox is 3 to 10 lowercase ASCII letters, optionally followed by plus and 1 to 3 ASCII digits, then @team.test. No other local-part characters, spaces or uppercase.",r"[a-z]{3,10}(?:\+[0-9]{1,3})?@team\.test","abc@team.test|abcdefghij@team.test|abc+0@team.test|abc+999@team.test|alice@team.test|alice+12@team.test|bot+001@team.test|xyz+9@team.test","ab@team.test|abcdefghijk@team.test|abc+@team.test|abc+1234@team.test|Abc@team.test|abc@teamXtest|abc_1@team.test", "Optional plus tags have their own length and alphabet.")
C("A social handle begins @ and contains 4 to 12 lowercase ASCII letters, digits or underscores after it. The handle must start with a letter and end with a letter or digit; adjacent underscores are forbidden.",r"@(?=[a-z0-9_]{4,12}$)(?!.*__)[a-z][a-z0-9_]*[a-z0-9]","@abcd|@abc1|@a_bc|@a1_2|@abcdefghijkl|@a_b_c_d_e_f1|@user_42|@x123", "@abc|@abcdefghijklm|@1abc|@abc_|@ab__c|@Abcd|@ab-c", "Length, endpoints and underscore adjacency are separate rules.")
bounded("A departmental account ID is dept- then a canonical integer 10 through 72 and literal @internal. No spaces or leading zeros.","dept-",10,72,r"(?:[1-6][0-9]|7[0-2])","@internal")
C("A login is 6 through 14 lowercase ASCII letters or digits and must contain both kinds. It may start with a digit; exact names guest1 and admin1 are reserved.",r"(?!guest1$|admin1$)(?=[a-z0-9]{6,14}$)(?=.*[a-z])(?=.*[0-9])[a-z0-9]+","user01|1alice|abcdef12345678|guest12|admin12|12345a|a00000|foo123","guest1|admin1|abcdef|123456|abc12|abcdef123456789|ABC123|abc_12", "Reserved names are exact matches, and a digit-first login is allowed.")
search("Search a message for a lowercase eight-letter user name immediately after user= and before semicolon. Surrounding text is unrestricted.","user=",r"[a-z]{8}",["aaaaaaaa","zzzzzzzz","abcdefgh","username","customer","operator","testuser","qwertyui"],";",["aaaaaaa","aaaaaaaaa","AAAAAAAA","abcdefg1","abcdefg_","abcdefgé"])
search("Find an account slot 01 through 24 immediately between lowercase account[ and ]. Search anywhere; the two-digit spelling is mandatory.","account[",r"(?:0[1-9]|1[0-9]|2[0-4])",["01","02","09","10","12","20","23","24"],"]",["00","25","1","001","a1","+1"])
C("A forum username has 3 to 16 lowercase ASCII letters or digits, starts with a letter, and may contain single hyphens internally, never adjacent or at the ends. Count hyphens toward the length.",r"(?=.{3,16}$)[a-z][a-z0-9]*(?:-[a-z0-9]+)*","abc|a-b|alice-2|abcdefghijklmnop|a1-b2-c3|user123|x-9|foo-bar","ab|abcdefghijklmnopq|1abc|-abc|abc-|ab--c|Abc|ab_c", "Segmented hyphens and overall length must agree.")
equal_pair("An account confirmation is login: followed by two identical lowercase ASCII usernames of 3 to 8 letters, separated by slash. No spaces.","login:","/",r"[a-z]{3,8}",["abc","xyz","abcdefgh","alice","charlie","user","adminx","sample"])
C("A migration address is a lowercase ASCII username 3 to 8 letters at old.test, then an arrow ->, then the exact same username at new.test. No spaces or plus tags.",r"([a-z]{3,8})@old\.test->\1@new\.test","abc@old.test->abc@new.test|xyz@old.test->xyz@new.test|abcdefgh@old.test->abcdefgh@new.test|alice@old.test->alice@new.test|bob@old.test->bob@new.test|user@old.test->user@new.test|sample@old.test->sample@new.test|charlie@old.test->charlie@new.test","abc@old.test->xyz@new.test|ab@old.test->ab@new.test|abcdefghi@old.test->abcdefghi@new.test|ABC@old.test->ABC@new.test|abc@oldXtest->abc@new.test|abc@old.test ->abc@new.test", "Username equality and literal domains both matter.")
unicode_name("An international display name is 2 to 12 Unicode letters only, with no spaces, digits or combining marks. Length counts code points.")
C("A support search should succeed if any entire LF-separated line is suspended: followed by a lowercase ASCII username of 3 to 8 letters. Other lines may be arbitrary; a carriage return is not stripped from a line.",r"(?:^|\n)suspended:[a-z]{3,8}(?=\n|(?![\s\S]))","suspended:abc|suspended:abcdefgh|x\nsuspended:alice\ny|\nsuspended:xyz\n|suspended:user\ntext|text\nsuspended:sample|a\nb\nsuspended:charlie\nz|suspended:bob", "suspended:ab|suspended:abcdefghi|suspended:ABC|x suspended:abc|suspended:abc x|Suspended:abc|suspended:abc\r|suspended:abc1", "Match a complete line, not a substring of it.",contains=True)
line_copy("An LF-only account receipt has handle= and @ plus four lowercase ASCII letters on the first line, then copy= and the exact same handle on the second. No final LF or spaces.","handle=",r"@[a-z]{4}",["@abcd","@wxyz","@aaaa","@zzzz","@user","@team","@test","@qwer"])
C("A namespaced login is a lowercase ASCII team name of 3 to 8 letters, colon, a lowercase ASCII username of 3 to 8 letters. Team and username must differ, and neither may be the exact reserved name root.",r"(?!root:)([a-z]{3,8}):(?!\1$|root$)[a-z]{3,8}","team:alice|alice:team|abc:xyz|abcdefgh:user|roots:rooted|foo:bar|ops:admin|staff:tester","root:alice|alice:root|abc:abc|ab:xyz|abc:abcdefghi|ABC:xyz|abc: xyz", "Exclude exact names rather than prefixes and compare whole fields.")
C("A tagged mailbox is a lowercase ASCII username of 3 to 8 letters, plus, a lowercase ASCII tag of 2 to 6 letters, at team.test. The tag must occur as a substring of the username; no other characters or uppercase.",r"(?=[a-z]{3,8}\+([a-z]{2,6})@team\.test$)[a-z]*\1[a-z]*\+\1@team\.test","alice+ali@team.test|alice+ice@team.test|abc+ab@team.test|abcdef+abcdef@team.test|foobar+bar@team.test|user+us@team.test|testing+test@team.test|charlie+lie@team.test","alice+bob@team.test|abc+a@team.test|ab+ab@team.test|abcdefghi+abc@team.test|abcdefg+abcdefg@team.test|Alice+ali@team.test|alice+ali@teamXtest", "The tag is bounded independently and must be found in the local username.")
finish()
